test('EP1/EP4: real proxy listener rejects duplicate forwarding field-lines before work', async () => {
  const s = system({ edgePolicy: edge({ proxyMode: true, trustedProxies: ['127.0.0.1'] }) });
  const server = createAuthenticatedWebServer(s.web, { proxy: { cleartextBackend: true } });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const send = (headers) => new Promise((resolve, reject) => {
    const req = httpRequest({ host: '127.0.0.1', port: server.address().port, method: 'GET', path: '/healthz', headers }, (res) => {
      let body = ''; res.setEncoding('utf8'); res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => resolve({ status: res.statusCode, body }));
    });
    req.on('error', reject); req.end();
  });
  try {
    const duplicateSets = [
      { Forwarded: ['for=198.51.100.1;proto=https', 'for=198.51.100.2;proto=https'] },
      { 'X-Forwarded-For': ['198.51.100.1', '198.51.100.2'], 'X-Forwarded-Proto': 'https' },
      { 'X-Forwarded-For': '198.51.100.1', 'X-Forwarded-Proto': ['https', 'https'] },
    ];
    for (const headers of duplicateSets) assert.equal((await send(headers)).status, 400);
    assert.equal((await send({ Forwarded: 'for=198.51.100.1;proto=https' })).status, 200);
    for (const proto of ['HTTP', 'HTTPS', 'hTtPs']) {
      const expected = proto.toLowerCase() === 'http' ? 400 : 200;
      assert.equal((await send({ 'X-Forwarded-For': '198.51.100.1', 'X-Forwarded-Proto': proto })).status, expected);
    }
    assert.equal((await send({ 'X-Forwarded-For': '198.51.100.1', 'X-Forwarded-Proto': 'FTP' })).status, 400);
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
  assert.equal(s.sessions.events().length, 0); assert.deepEqual(s.fleetCalls, []);
  const audits = s.coordination.events().filter((event) => event.payload?.kind === 'proxy_refused');
  assert.equal(audits.length, 5);
  const serialized = JSON.stringify(audits);
  for (const address of ['198.51.100.1', '198.51.100.2', '2001:db8::1']) assert.equal(serialized.includes(address), false);
});

test('EP2/EP3: ticket quota and exact ticket state roll back when HTTP delivery fails', async () => {
  const s = system({ edgePolicy: edge({ limits: { ticket: 1 } }) });
  const issued = s.sessions.issue({ userId: 'u', authMethod: 'bearer', capabilities: ['observe'], repoIds: ['repo-a'], ttlMs: 60_000 }, { actor: 'provider' });
  const invoke = async (res) => {
    const req = new EventEmitter(); Object.assign(req, {
      method: 'POST', url: '/v1/stream-tickets',
      headers: { origin: ORIGIN, 'content-type': 'application/json', authorization: `Bearer ${issued.token}` },
      socket: { encrypted: true, remoteAddress: '127.0.0.1' }, destroy() {},
    });
    const pending = s.web.handle(req, res);
    queueMicrotask(() => { req.emit('data', Buffer.from('{"repoId":"repo-a"}')); req.emit('end'); });
    await pending;
  };
  class BrokenHead extends Response { writeHead() { throw new Error('reset before headers'); } }
  class BrokenEnd extends Response { end() { throw new Error('reset during body'); } }
  for (const res of [new BrokenHead(), new BrokenEnd()]) {
    await invoke(res);
    assert.equal(s.web.stream.tickets.size, 0);
    assert.equal(s.web.edge.quotas.ticket.size, 0);
  }
  const options = { path: '/v1/stream-tickets', body: { repoId: 'repo-a' }, headers: { authorization: `Bearer ${issued.token}` } };
  assert.equal((await request(s.web, options)).status, 201);
  assert.equal((await request(s.web, options)).status, 429);
  assert.equal(s.coordination.events().filter((event) => event.payload?.kind === 'stream_ticket_delivery_failed').length, 2);
});
